from pathlib import Path
import base64
root=Path("WakeGuard/app")
dst=root/"src/main/java/jp/wakeguard/alarm/StreakCompanionView.java"
dst.write_bytes(base64.b64decode(""""""))
# Repair one malformed literal in the embedded source payload.
text=dst.read_text().replace("new float[]{0f,.48f,.76f,1g}", "new float[]{0f,.48f,.76f,1f}")
text=text.replace("viewer.transformToUnitCube();", "viewer.transformToUnitCube(new com.google.android.filament.utils.Float3(0f,0f,-4f));")
dst.write_text(text)
p=root/"build.gradle.kts"
s=p.read_text()
s=s.replace('versionCode = 160','versionCode = 170',1).replace('versionName = "2.6.0"','versionName = "2.7.0"',1)
s=s.replace('compileSdk = 36','compileSdk = 37',1)
needle='implementation("androidx.browser:browser:1.10.0")'
deps='''implementation("androidx.browser:browser:1.10.0")
    implementation("com.google.android.filament:filament-android:1.77.1")
    implementation("com.google.android.filament:gltfio-android:1.77.1")
    implementation("com.google.android.filament:filament-utils-android:1.77.1")'''
if needle not in s: raise SystemExit("Android dependency marker missing")
s=s.replace(needle,deps,1)
p.write_text(s)
src=dst.read_text()
assert 'new ModelViewer(surface, engine, uiHelper, null)' in src
assert 'viewer.loadModelGlb(model)' in src
assert 'versionName = "2.7.0"' in p.read_text()
print("Android 2.7.0 3D model patch applied")
